import math
import random


def gf2_left_nullity(rows: list[int], ncols: int) -> int:
    """Left nullity of an r x c GF(2) matrix (rows as bitmasks) = r - rank."""
    piv: dict[int, int] = {}
    rank = 0
    for v in rows:
        for b in range(ncols - 1, -1, -1):
            if not (v >> b) & 1:
                continue
            if b in piv:
                v ^= piv[b]
            else:
                piv[b] = v
                rank += 1
                break
    return len(rows) - rank


def instrument_is_saturated(r: int, c: int, cap: int, counts_vectors: bool = False) -> bool:
    """Saturation check: by rank-nullity, nullity >= r - c; the capped reading is then
    forced to equal cap.  For vector counts, 2^(r-c) - 1 >= cap suffices."""
    excess = max(r - c, 0)
    if counts_vectors:
        return 2 ** excess - 1 >= cap
    return excess >= cap


if __name__ == "__main__":
    rng = random.Random(1)
    c = 120
    for e in (0, 6, 59, 60, 90):
        rows = [sum(1 << j for j in rng.sample(range(c), 10)) for _ in range(c + e)]
        nu = gf2_left_nullity(rows, c)
        print(e, nu, min(60, nu), instrument_is_saturated(c + e, c, 60), instrument_is_saturated(c + e, c, 60, True))

import math
from fractions import Fraction


def loglog_slope(W1: float, W2: float, S1: float, S2: float) -> float:
    return math.log(S2 / S1) / math.log(W2 / W1)


def certify_slope_bracket(growth: Fraction, width: Fraction, p: int, q: int) -> bool:
    """Certify ln(growth)/ln(width) < p/q via the exact rational test growth^q < width^p."""
    return growth ** q < width ** p


def no_inversion_verdict(s: float, t: float, a: float, b: float) -> str:
    if not (0 < s < t):
        return "hypotheses 0 < s < t fail: no conclusion"
    Wc = (a / b) ** (1 / (t - s))
    return (f"S/C = (a/b) W^-{t - s:.4f} strictly decreasing to 0; "
            f"cost dominates for all W >= {max(Wc, 0):.4g}; no inversion")


if __name__ == "__main__":
    g, w = Fraction(794, 100), Fraction(53, 10)
    print("s =", loglog_slope(1.0, 5.30, 1.0, 7.94))
    print("s < 5/4 certified:", certify_slope_bracket(g, w, 5, 4))      # 7.94^4 < 5.3^5
    print("s > 6/5 certified:", w ** 6 < g ** 5)                         # 5.3^6 < 7.94^5
    print(no_inversion_verdict(loglog_slope(1.0, 5.30, 1.0, 7.94), 1.819, 5.0, 1.0))

import math


def integer_root(N: int, d: int) -> int:
    m = int(round(N ** (1.0 / d)))
    while m ** d > N:
        m -= 1
    while (m + 1) ** d <= N:
        m += 1
    return m


def base_m_polynomial(N: int, d: int) -> tuple[int, list[int]]:
    """Return (m, coefficients const-first) with m^d <= N < m^(d+1), f(m) = N, deg f = d, all c_i < m."""
    m = integer_root(N, d)
    if m < 2 or not (m ** d <= N < m ** (d + 1)):
        raise ValueError("no admissible m for this degree")
    coeffs, n = [], N
    while n:
        n, r = divmod(n, m)
        coeffs.append(r)
    assert len(coeffs) == d + 1 and coeffs[-1] != 0 and max(coeffs) < m
    return m, coeffs


def norm_bound(coeffs: list[int], U: int) -> int:
    d = len(coeffs) - 1
    return (d + 1) * max(abs(c) for c in coeffs) * U ** d


def balanced_degree(u: float, x: float) -> tuple[float, float, int]:
    """Real optimum d* = sqrt(x/u), floor value 2 sqrt(ux), and best integer degree."""
    dstar = math.sqrt(x / u)
    best = min(range(1, max(2, int(2 * dstar) + 2)), key=lambda k: k * u + x / k)
    return dstar, 2 * math.sqrt(u * x), best


if __name__ == "__main__":
    N = 1000000016000000063
    for d in (3, 4, 5):
        m, f = base_m_polynomial(N, d)
        print(d, m, f, norm_bound(f, 1000))
    print(balanced_degree(20.0, 700.0))
